using System; using System.Collections.Generic; using System.Threading; using System.Threading.Tasks; using PhotoBooth.Core.Models; using PhotoBooth.Core.Persistence; using PhotoBooth.Core.Services;
namespace PhotoBooth.Business.Services { public sealed class PresetService : IPresetService { private readonly IPresetRepository _repository; public PresetService(IPresetRepository repository){_repository=repository;} public Task<IReadOnlyList<Preset>> GetAllAsync(CancellationToken token)=>_repository.GetAllAsync(token); public Task<Preset> GetAsync(Guid id,CancellationToken token)=>_repository.GetAsync(id,token); public Task SaveAsync(Preset value,CancellationToken token)=>_repository.SaveAsync(value,token); public async Task SetPinnedAsync(Guid id,bool isPinned,CancellationToken token){var value=await _repository.GetAsync(id,token);if(value==null)throw new InvalidOperationException("Không tìm thấy preset.");value.IsPinned=isPinned;value.ModifiedAtUtc=DateTime.UtcNow;await _repository.SaveAsync(value,token);} public Task DeleteAsync(Guid id,CancellationToken token)=>_repository.DeleteAsync(id,token); } }
